//! City Gen v4, phase 1: the airport claims its land before the graded roads, and the
//! validator holds it (claims.rs, validate.rs). The live Commons is generated by the
//! shared `commons3` (v3_tests.rs).

use super::claims::Airport;
use super::profile::district;
use super::v3_tests::{commons3, island3};
use super::*;

fn commons_claim() -> Airport {
    Airport::of(&commons3().layers.sites).expect("the Commons has an airport")
}

#[test]
fn the_commons_breaks_no_hard_rule() {
    let v = validate::hard(&commons3().layers);
    assert!(v.is_empty(), "{}", validate::report(&v));
}

#[test]
fn no_highway_or_ring_runs_through_the_commons_airport() {
    let a = commons_claim();
    let mut behind = false;
    for e in commons3().layers.roads.edges.iter().filter(|e| roads::is_graded(e.class)) {
        for s in e.points.windows(2) {
            let (p, q) = ((s[0][0], s[0][2]), (s[1][0], s[1][2]));
            assert!(!a.meets_seg(p, q, e.width / 2), "{} {} enters the airport", e.class, e.name);
            // only the ring runs in the corridor behind the terminal
            assert!(e.class == "ring" || !a.in_corridor(p, q, e.width / 2), "{} {} behind the terminal", e.class, e.name);
            behind |= e.class == "ring" && a.in_corridor(p, q, 0);
        }
    }
    assert!(behind, "the ring passes behind the terminal, under the skybridge");
    // and it is still a ring: all six sections
    let names: std::collections::BTreeSet<&str> = commons3().layers.roads.edges.iter().filter(|e| e.class == "ring").map(|e| e.name.as_str()).collect();
    assert_eq!(names.len(), 6, "{names:?}");
}

#[test]
fn every_lot_and_the_commons_airport_stay_where_they_were() {
    // the pins of v3_tests hold the airport; here: the forecourt, car park and tower keep
    // roads off them too, and the HQ pool is untouched (v3_tests counts the 64 HQ lots)
    let a = commons_claim();
    assert_eq!(a.landside, 4);
    for e in &commons3().layers.roads.edges {
        for s in e.points.windows(2) {
            assert!(!a.polys[..a.landside].iter().any(|p| Airport::polys_meet(p, &[(s[0][0], s[0][2]), (s[1][0], s[1][2])], e.width / 2)), "{} {} crosses the landside", e.class, e.name);
        }
    }
}

#[test]
fn the_airports_grounds_grow_no_trees() {
    let d = &commons3().layers.districts;
    let a = commons_claim();
    let (forest, park) = (district::NAMES2.iter().position(|&n| n == "forest").unwrap() as u8, district::NAMES2.iter().position(|&n| n == "park").unwrap() as u8);
    let mut cells = 0;
    for iz in 0..d.n {
        for ix in 0..d.n {
            let q = (d.origin_cm + ix as i64 * d.cell_cm + d.cell_cm / 2, d.origin_cm + iz as i64 * d.cell_cm + d.cell_cm / 2);
            if a.contains(q) {
                cells += 1;
                let k = d.kinds[iz * d.n + ix];
                assert!(k != forest && k != park, "a tree district in the airport at {q:?}");
            }
        }
    }
    assert!(cells > 1_000, "{cells} cells under the claim");
}

#[test]
fn a_personal_island_has_no_airport_and_nothing_to_break() {
    assert!(Airport::of(&island3().layers.sites).is_none());
    assert!(validate::hard(&island3().layers).is_empty());
}

#[test]
fn other_commons_seeds_keep_off_their_airport_too() {
    // a few seeds with the Commons' profile, airports facing different ways
    for id in ["v4seed9@3", "v4seed21@3", "v4seed41@3"] {
        let w = generate(id, &[]).unwrap();
        assert!(Airport::of(&w.layers.sites).is_some(), "{id}: no airport");
        let v = validate::hard(&w.layers);
        assert!(v.is_empty(), "{id}:\n{}", validate::report(&v));
    }
}

/// Every one of 50 Commons-profile seeds that generates passes the validator (one,
/// v4seed7, has too few HQ lots, as before v4). Slow in a debug build: run it with
/// `cargo test --release -- --ignored fifty`.
#[test]
#[ignore]
fn fifty_seeds_break_no_hard_rule() {
    for i in 1..=50 {
        let id = format!("v4seed{i}@3");
        let Ok(w) = generate(&id, &[]) else { continue };
        let v = validate::hard(&w.layers);
        assert!(v.is_empty(), "{id}:\n{}", validate::report(&v));
    }
}
